<?php
namespace Tests\Feature;
use App\Models\{MarketingStoryboardWorkspace as Workspace,MarketingVideoFilm,MarketingVideoClip,MarketingStoryboardProviderCall};
use App\Services\Marketing\{MarketingStoryboardWorkspace,MarketingStoryboardHandoff,MarketingProductionPreparation,MarketingStoryboardProduction,MarketingVideoFiles,MarketingVideoCompositor};
use Illuminate\Support\Facades\{Http,Queue};
use Illuminate\Support\Str;
class MarketingEconomyVideoAcceptanceTest extends MarketingStoryboardTrialScopeTest {
 public function test_fake_trial_runs_15_and_fast_and_settles_without_changing_original_or_creating_film():void {
  [$p,$s]=$this->sample();$w=Workspace::where('project_id',$p->id)->firstOrFail();$profile=$w->profile;$profile['voice']=['mode'=>'auto'];$w->update(['profile'=>$profile]);$s=app(MarketingStoryboardWorkspace::class)->snapshot($p->id,$p->owner_id);app(MarketingStoryboardHandoff::class)->confirm($p->id,$p->owner_id,(string)Str::uuid(),$s['story_version']);
  $price=['version'=>'fake-only-economy','cap_microusd'=>400000,'credit_usd'=>10/650,'access_verified_at'=>'fixture','pricing_verified_at'=>'fixture'];
  config(['marketing.native.api_key'=>'fake-evolink','marketing.storyboard.live_enabled'=>true,'marketing.storyboard.live_grant'=>['project_id'=>$p->id,'owner_id'=>$p->owner_id,'reference'=>'fake-only-economic','roles'=>['upload','video'],'expires_at'=>now()->addHour()->toIso8601String(),'max_total_microusd'=>1000000,'max_calls'=>4], 'marketing.storyboard.roles.video'=>$price+['model'=>'seedance-1.5-pro','tiers'=>['ordinary']], 'marketing.storyboard.video_models'=>['doubao-seedance-1.0-pro-fast'=>array_replace($price,['model'=>'doubao-seedance-1.0-pro-fast','cap_microusd'=>100000,'source_has_audio'=>false,'source_audio_verified_at'=>'fixture'])], 'marketing.storyboard.roles.upload'=>['model'=>'fake-upload','version'=>'fixture','cap_microusd'=>1,'fee_microusd'=>0,'pricing_verified_at'=>'fixture'], 'marketing.storyboard.audio.native'=>['model'=>'seedance-1.5-pro','version'=>'fake-only-economy','verified_at'=>'fixture','languages'=>['English','zh-MY'],'exact_script'=>true,'lip_sync'=>true]]);
  Queue::fake();Http::fake(['https://files-api.evolink.ai/api/v1/files/upload/stream'=>Http::response(['success'=>true,'data'=>['file_id'=>'fake','file_url'=>'https://files.evolink.ai/fake.png','expires_at'=>now()->addHours(72)->toIso8601String()]]),'https://api.evolink.ai/v1/videos/generations'=>fn($r)=>Http::response(['id'=>$r['model']==='seedance-1.5-pro'?'fake-15':'fake-fast','usage'=>['credits_reserved'=>$r['model']==='seedance-1.5-pro'?21.3408:4.5]]),'https://api.evolink.ai/v1/tasks/*'=>fn($r)=>Http::response(['id'=>basename($r->url()),'status'=>'completed','usage'=>['credits_used'=>str_ends_with($r->url(),'fake-15')?21.3408:4.5],'results'=>['https://files.evolink.ai/fake.mp4']])]);
  $this->mock(MarketingVideoFiles::class)->shouldReceive('download')->twice()->andReturn(['path'=>'fixture/raw.mp4','sha256'=>str_repeat('a',64)]);
  $this->mock(MarketingVideoCompositor::class)->shouldReceive('storyboardClip')->twice()->andReturn(['path'=>'fixture/output.mp4','sha256'=>str_repeat('b',64),'editing_source'=>['path'=>'fixture/raw.mp4','sha256'=>str_repeat('a',64)]]);
  $svc=app(MarketingStoryboardProduction::class);
  foreach([1=>'seedance-1.5-pro',0=>'doubao-seedance-1.0-pro-fast'] as $i=>$model){$plan=app(MarketingProductionPreparation::class)->prepareStoryboard($p->id,$p->owner_id,(string)Str::uuid(),$s['story_version'],$s['scenes'][$i]['scene_id']);$this->assertEmpty($plan->manifest['blockers']);$this->assertSame($model,$plan->manifest['configuration']['video']['model']);$run=$svc->start($p->id,$p->owner_id,$s['story_version'],$plan->id,true);for($n=0;$n<6;$n++)$svc->advance($run->id);$this->assertSame('completed',$run->fresh()->status);$this->assertFalse($run->fresh()->result['full_film_completed']);}
  $this->assertSame(0,MarketingVideoFilm::where('project_id',$p->id)->count());$this->assertSame(4,MarketingStoryboardProviderCall::where('project_id',$p->id)->count());$this->assertSame($s['story_version'],app(MarketingStoryboardWorkspace::class)->snapshot($p->id,$p->owner_id)['story_version']);Http::assertSentCount(6);
 }
}
